<?php $pageTitle='Contact';require_once __DIR__.'/functions.php';$ok='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$st=db()->prepare("INSERT INTO messages(name,email,message) VALUES(?,?,?)");$st->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['message'])]);$ok='Your message has been sent to the administrator.';}catch(Throwable $e){$error='Could not send message. Please try again.';}}include 'includes/header.php';?><section class="page-head"><div class="container"><h1>Contact Us</h1><p class="muted">Send a message for course, notes or website questions.</p></div></section><section class="section"><form class="form-box panel" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php if($ok):?><div class="notice"><?=e($ok)?></div><?php endif;?><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><label>Name</label><input required name="name"><label>Email</label><input required type="email" name="email"><label>Message</label><textarea required name="message" rows="6"></textarea><button class="primary" type="submit">Send Message</button></form></section><?php include 'includes/footer.php';?>
